m.textContent="          async function subscribeUserToPushOnMobile(userId, publicKey) {\n            if ('serviceWorker' in navigator && 'PushManager' in window) {\n              const reg = await navigator.serviceWorker.ready;\n              \n              if (Notification.permission === 'denied') {\n                console.warn('\u0421\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u043d\u044f \u0437\u0430\u0431\u043b\u043e\u043a\u043e\u0432\u0430\u043d\u043e \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0456');\n                return;\n              }\n\n              const permission = await Notification.requestPermission();\n              if (permission !== 'granted') return;\n\n              let cleanKey = publicKey.trim().replace(/\\s/g, '');\n              const padding = '='.repeat((4 - cleanKey.length % 4) % 4);\n              const base64 = (cleanKey + padding).replace(/\\-/g, '+').replace(/_/g, '/');\n              \n              const rawData = window.atob(base64);\n              const outputArray = new Uint8Array(rawData.length);\n              for (let i = 0; i < rawData.length; ++i) {\n                outputArray[i] = rawData.charCodeAt(i);\n              }\n\n              const subscription = await reg.pushManager.subscribe({\n                userVisibleOnly: true,\n                applicationServerKey: outputArray\n              });\n\n              console.log('\u0422\u043e\u043a\u0435\u043d \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u043e!');\n\n              // \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e \u043f\u0456\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0454\u043c\u043e IP-\u0430\u0434\u0440\u0435\u0441\u0443 \u043a\u043e\u043c\u043f'\u044e\u0442\u0435\u0440\u0430, \u0437 \u044f\u043a\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043e \u0441\u0430\u0439\u0442, \u0437\u0430\u043c\u0456\u0441\u0442\u044c localhost\n              const backendUrl = 'https://back-oms.onrender.com/api/notifications/subscribe/' + userId;\n\n              await fetch(backendUrl, {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify(subscription)\n              });\n              \n              console.log('\u041f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u043e\u0432\u0430\u043d\u043e \u043d\u0430 \u0431\u0435\u043a\u0435\u043d\u0434\u0456!');\n            }\n          }\n          // \u041e\u0434\u0440\u0430\u0437\u0443 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0454\u043c\u043e\n          subscribeUserToPushOnMobile("+a+", '"+A.n(q)+"');\n        "
